<script setup lang="ts">import {ref,computed} from 'vue';import {ChevronDown,Copy,Check} from 'lucide-vue-next';import PageHeader from '../components/PageHeader.vue';import {specificationGroups} from '../data/mock';import {useSelectedVehicle} from '../composables/useSelectedVehicle';const {vehicle,base}=useSelectedVehicle();const golfGroups=[{title:'Engine',items:[['Engine','EA888 Gen 3'],['Displacement','1,984 cc'],['Power','169 kW'],['Torque','350 Nm'],['Fuel','Petrol']]},{title:'Fluids',items:[['Engine oil','5.7 L'],['Recommended specification','VW 504 00'],['Coolant','G13'],['Brake fluid','DOT 4']]},{title:'Wheels & Tires',items:[['Front & rear','225/40 R18'],['Wheel','7.5J × 18'],['Bolt pattern','5 × 112'],['Tyre pressure','2.6 bar front · 2.6 bar rear']]},{title:'Maintenance intervals',items:[['Engine oil','15,000 km / 12 months'],['DSG service','60,000 km'],['Brake fluid','24 months'],['Inspection','12 months']]},{title:'Vehicle',items:[['Generation','Mk7'],['Transmission','6-speed DSG'],['Drive','Front-wheel drive'],['First registration','8 March 2017'],['VIN','WVWZZZAUZHW123456']]}];const groups=computed(()=>vehicle.value.id==='golf-gti'?golfGroups:specificationGroups);const open=ref(['Engine','Fluids','Wheels & Tires','Vehicle']);const copied=ref('');const copy=async(v:string)=>{await navigator.clipboard.writeText(v);copied.value=v;setTimeout(()=>copied.value='',1200)};const toggle=(t:string)=>open.value=open.value.includes(t)?open.value.filter(x=>x!==t):[...open.value,t]

</script>
<template><PageHeader title="Specifications" :back="base"/><div class="container-app max-w-4xl py-7"><p class="eyebrow">{{vehicle.make}} {{vehicle.model}}</p><h1 class="page-title mt-2">Technical details</h1><p class="mt-3 text-muted">Essential specifications for servicing and ownership.</p><div class="mt-8 space-y-3"><section v-for="g in groups" class="card overflow-hidden"><button class="flex w-full items-center justify-between p-5 text-left" @click="toggle(g.title)"><h2 class="section-title">{{g.title}}</h2><ChevronDown :size="19" class="transition" :class="{'rotate-180':open.includes(g.title)}"/></button><div v-if="open.includes(g.title)" class="border-t px-5"><div v-for="item in g.items" class="flex items-center justify-between gap-5 border-b py-4 last:border-0"><span class="text-sm text-muted">{{item[0]}}</span><span class="flex items-center gap-2 text-right text-sm font-semibold nums">{{item[1]}}<button v-if="item[0]==='VIN'||item[0]==='Recommended specification'" @click="copy(item[1])" class="grid h-8 w-8 place-items-center rounded-lg text-muted hover:bg-stone-100" :aria-label="`Copy ${item[0]}`"><Check v-if="copied===item[1]" :size="15" class="text-success"/><Copy v-else :size="15"/></button></span></div></div></section></div><p class="mt-6 text-xs leading-5 text-muted">Specifications are shown for prototype purposes. Always confirm service requirements with the vehicle manufacturer or a qualified workshop.</p></div></template>
